    "stem": "Tuncay, üçüncü kişi Sinan'ın ağır ve yakın bir tehdidi altında evini Gökhan'a satar. Gökhan, tehditten habersizdir ve durumu bilmesi de gerekmemektedir. 6098 sayılı Türk Borçlar Kanunu'na göre bu olayla ilgili aşağıdaki ifadelerden hangisi doğrudur?",
