    "qNumber": 19,
    "stem": "Seçkin, silahını doğrultarak ve karşı koyması hâlinde onu öldüreceğini söyleyerek Tarık'ı, komşusu Mert'in dükkânının camlarını kırmaya zorlar. Tarık, karşı koyamayacağı bu tehdit altında camları kırar. 5237 sayılı Türk Ceza Kanunu'na göre bu olayla ilgili aşağıdaki ifadelerden hangisi doğrudur?",
