    "qNumber": 5,
    "stem": "Kamu görevlisi Ebru'ya verilen kınama cezası 3 Mart 2026 tarihinde kendisine tebliğ edilir. Ebru, bu işlemin iptali istemiyle 20 Mayıs 2026 tarihinde idare mahkemesinde dava açar. Özel kanunda ayrı bir süre öngörülmemiştir ve süreyi durduran veya kesen bir başvuru yapılmamıştır. 2577 sayılı İdari Yargılama Usulü Kanunu'na göre mahkemenin ilk inceleme üzerine vereceği karar aşağıdakilerden hangisidir?",
