    "qNumber": 6,
    "stem": "1971 tarihli eserinde adaleti \"hakkaniyet olarak adalet\" biçiminde kavramlaştırmıştır. Toplumun temel ilkelerinin, kimsenin kendi toplumsal konumunu, yeteneklerini ve çıkarlarını bilmediği bir \"cehalet peçesi\" arkasında, varsayımsal bir \"başlangıç durumunda\" seçileceğini ileri sürmüştür. Eşitsizliklerin ancak toplumun en dezavantajlı kesiminin yararına olduğu ölçüde meşru olacağını savunan \"fark ilkesi\" de ona aittir.\nHakkında bilgiler verilen bu düşünür aşağıdakilerden hangisidir?",
