    "stem": "1748 yılında yayımlanan eserinde kanunların, ülkenin iklimi, coğrafyası, dini ve gelenekleri gibi etkenlerle ilişkisini inceleyerek \"kanunların ruhunu\" açıklamaya çalışmıştır. Özgürlüğün ancak iktidarın iktidarı durdurduğu bir düzende korunabileceğini savunmuş, yasama, yürütme ve yargı güçlerinin ayrı ellerde bulunması gerektiğini sistemli biçimde ortaya koymuştur.\nHakkında bilgiler verilen bu düşünür aşağıdakilerden hangisidir?",
